  fun writeRuntimeEvent(
    arena: PointerScope,
    value: RuntimeEvent,
  ): MaplibreNativeC.mln_runtime_event {
    val result = MaplibreNativeC.mln_runtime_event()
    result.type(value.type.rawValue.toInt())
    result.source_type(value.sourceType.rawValue.toInt())
    result.source(value.source.toLong())
    result.code(value.code)
    when (val variant = value.payload) {
      is RuntimeEventPayload.RenderFrame -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME)
        result
          .payload()
          .render_frame(GeneratedValues.writeRuntimeEventRenderFrame(arena, variant.value))
      }
      is RuntimeEventPayload.RenderMap -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP)
        result
          .payload()
          .render_map(GeneratedValues.writeRuntimeEventRenderMap(arena, variant.value))
      }
      is RuntimeEventPayload.TileAction -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION)
        result
          .payload()
          .tile_action(GeneratedValues.writeRuntimeEventTileAction(arena, variant.value))
      }
      is RuntimeEventPayload.OfflineRegionStatus -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS)
        result
          .payload()
          .offline_region_status(
            GeneratedValues.writeRuntimeEventOfflineRegionStatus(arena, variant.value)
          )
      }
      is RuntimeEventPayload.OfflineRegionResponseError -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR)
        result
          .payload()
          .offline_region_response_error(
            GeneratedValues.writeRuntimeEventOfflineRegionResponseError(arena, variant.value)
          )
      }
      is RuntimeEventPayload.OfflineRegionTileCountLimit -> {
        result.payload_type(
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT
        )
        result
          .payload()
          .offline_region_tile_count_limit(
            GeneratedValues.writeRuntimeEventOfflineRegionTileCountLimit(arena, variant.value)
          )
      }
      is RuntimeEventPayload.CameraTransitionFinished -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED)
        result
          .payload()
          .camera_transition_finished(
            GeneratedValues.writeRuntimeEventCameraTransitionFinished(arena, variant.value)
          )
      }
      RuntimeEventPayload.None -> {
        result.payload_type(MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_NONE)
      }
      is RuntimeEventPayload.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readRuntimeEvent(
    source: MaplibreNativeC.mln_runtime_event,
    message: String = "",
  ): RuntimeEvent =
    RuntimeEvent(
      type = RuntimeEventType(source.type().toUInt()),
      sourceType = RuntimeEventSourceType(source.source_type().toUInt()),
      source = source.source().toULong(),
      code = source.code(),
      payload =
        when (source.payload_type()) {
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME ->
            RuntimeEventPayload.RenderFrame(
              GeneratedValues.readRuntimeEventRenderFrame(source.payload().render_frame())
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP ->
            RuntimeEventPayload.RenderMap(
              GeneratedValues.readRuntimeEventRenderMap(source.payload().render_map())
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION ->
            RuntimeEventPayload.TileAction(
              GeneratedValues.readRuntimeEventTileAction(source.payload().tile_action())
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS ->
            RuntimeEventPayload.OfflineRegionStatus(
              GeneratedValues.readRuntimeEventOfflineRegionStatus(
                source.payload().offline_region_status()
              )
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR ->
            RuntimeEventPayload.OfflineRegionResponseError(
              GeneratedValues.readRuntimeEventOfflineRegionResponseError(
                source.payload().offline_region_response_error()
              )
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT ->
            RuntimeEventPayload.OfflineRegionTileCountLimit(
              GeneratedValues.readRuntimeEventOfflineRegionTileCountLimit(
                source.payload().offline_region_tile_count_limit()
              )
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED ->
            RuntimeEventPayload.CameraTransitionFinished(
              GeneratedValues.readRuntimeEventCameraTransitionFinished(
                source.payload().camera_transition_finished()
              )
            )
          MaplibreNativeC.MLN_RUNTIME_EVENT_PAYLOAD_NONE -> RuntimeEventPayload.None
          else ->
            RuntimeEventPayload.Unknown(
              source.payload_type().toUInt(),
              ByteArray(source.payload().sizeof()).also { BytePointer(source.payload()).get(it) },
            )
        },
      message = message,
    )

  fun writeRuntimeEventBatchView(
    arena: PointerScope,
    value: RuntimeEventBatchView,
  ): MaplibreNativeC.mln_runtime_event_batch_view {
    val result = MaplibreNativeC.mln_runtime_event_batch_view()
    result.size(result.sizeof())
    result.events(GeneratedValues.writeRuntimeEventArray(arena, value.events))
    result.event_count(value.events.size.toLong())
    return result
  }

  fun readRuntimeEventBatchView(
    source: MaplibreNativeC.mln_runtime_event_batch_view
  ): RuntimeEventBatchView =
    RuntimeEventBatchView(
      events =
        run {
          val count = (source.event_count()).toLong()
          val stride = (source.event_size()).toLong()
          require(count in 0..Int.MAX_VALUE.toLong())
          require(stride >= MaplibreNativeC.mln_runtime_event().sizeof().toLong())
          val dataSize = (source.messages_size()).toLong()
          List(count.toInt()) { index ->
            val item =
              MaplibreNativeC.mln_runtime_event(
                org.maplibre.nativeffi.internal.javacpp.JavaCppSupport.addressPointer(
                  source.events().address() + index.toLong() * stride
                )
              )
            val offset = (item.message_offset()).toLong()
            val length = (item.message_size()).toLong()
            require(offset >= 0 && length >= 0 && offset <= dataSize && length <= dataSize - offset)
            GeneratedValues.readRuntimeEvent(
              item,
              GeneratedValues.readRawBytes(BytePointer(source.messages()).position(offset), length)
                .decodeToString(),
            )
          }
        }
    )

