  fun writeOpenglContextDescriptor(
    arena: PointerScope,
    value: OpenglContextDescriptor,
  ): MaplibreNativeC.mln_opengl_context_descriptor {
    val result = MaplibreNativeC.mln_opengl_context_descriptor()
    result.size(result.sizeof())
    result.ownership(value.ownership.rawValue.toInt())
    when (val variant = value.data) {
      is OpenglContextDescriptorData.Wgl -> {
        result.platform(MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WGL)
        result.data().wgl(GeneratedValues.writeWglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Egl -> {
        result.platform(MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_EGL)
        result.data().egl(GeneratedValues.writeEglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Webgl -> {
        result.platform(MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WEBGL)
        result.data().webgl(GeneratedValues.writeWebglContextDescriptor(arena, variant.value))
      }
      is OpenglContextDescriptorData.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readOpenglContextDescriptor(
    source: MaplibreNativeC.mln_opengl_context_descriptor
  ): OpenglContextDescriptor =
    OpenglContextDescriptor(
      ownership = OpenglContextOwnership(source.ownership().toUInt()),
      data =
        when (source.platform()) {
          MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WGL ->
            OpenglContextDescriptorData.Wgl(
              GeneratedValues.readWglContextDescriptor(source.data().wgl())
            )
          MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_EGL ->
            OpenglContextDescriptorData.Egl(
              GeneratedValues.readEglContextDescriptor(source.data().egl())
            )
          MaplibreNativeC.MLN_OPENGL_CONTEXT_PLATFORM_WEBGL ->
            OpenglContextDescriptorData.Webgl(
              GeneratedValues.readWebglContextDescriptor(source.data().webgl())
            )
          else ->
            OpenglContextDescriptorData.Unknown(
              source.platform().toUInt(),
              ByteArray(source.data().sizeof()).also { BytePointer(source.data()).get(it) },
            )
        },
    )

