  fun rawBytes(arena: PointerScope, value: ByteArray): BytePointer =
    BytePointer(maxOf(1, value.size).toLong()).also { if (value.isNotEmpty()) it.put(*value) }

  fun readRawBytes(source: Pointer?, count: Long): ByteArray {
    require(count in 0..Int.MAX_VALUE.toLong())
    return ByteArray(count.toInt()).also { if (it.isNotEmpty()) BytePointer(source).get(it) }
  }

  fun optionalBytesView(arena: PointerScope, value: ByteArray?): MaplibreNativeC.mln_buffer_view =
    if (value == null) MaplibreNativeC.mln_buffer_view().data(null as Pointer?).size(0)
    else byteView(arena, value)

  fun optionalStringView(arena: PointerScope, value: String?): MaplibreNativeC.mln_buffer_view =
    optionalBytesView(arena, value?.encodeToByteArray())

  fun byteView(arena: PointerScope, value: ByteArray): MaplibreNativeC.mln_buffer_view =
    MaplibreNativeC.mln_buffer_view().data(rawBytes(arena, value)).size(value.size.toLong())

  fun stringView(arena: PointerScope, value: String): MaplibreNativeC.mln_buffer_view =
    byteView(arena, value.encodeToByteArray())

  fun readBytes(source: MaplibreNativeC.mln_buffer_view): ByteArray {
    require(source.size() in 0..Int.MAX_VALUE.toLong())
    return ByteArray(source.size().toInt()).also {
      if (it.isNotEmpty()) BytePointer(source.data()).get(it)
    }
  }

  fun readString(source: MaplibreNativeC.mln_buffer_view): String =
    readBytes(source).decodeToString()

  fun cString(arena: PointerScope, value: String): BytePointer {
    BindingStatus.requireArgument('\u0000' !in value) { "text contains an embedded NUL" }
    return rawBytes(arena, value.encodeToByteArray() + byteArrayOf(0))
  }
